// La API nueva espera un JSON con la imagen en base64
let base64Image = msg.payload.toString('base64');

msg.payload = {
    "image": base64Image
};

// Asegurar que enviamos JSON
msg.headers = {
    "Content-Type": "application/json"
};

return msg;

let msg1 = null; // Alerta MQTT
let msg3 = { payload: "" }; // Texto Dashboard

// Revisar si la API respondió correctamente y trajo rostros
if (msg.payload && msg.payload.success && msg.payload.rostros && msg.payload.rostros.length > 0) {

    // Tomar el rostro principal de la lista
    let rostro = msg.payload.rostros[0]; 

    if (rostro.reconocido) {
        let alertaJSON = {
            "equipo": "equipo1",
            "alerta": "persona_identificada",
            "identidad": rostro.nombre,
            "movimiento": true
        };
        msg1 = { payload: alertaJSON };
        msg3.payload = "🚨 Detectado: " + rostro.nombre.toUpperCase();
    } else {
        let alertaJSON = {
            "equipo": "equipo1",
            "alerta": "intruso_detectado",
            "movimiento": true
        };
        msg1 = { payload: alertaJSON };
        msg3.payload = "⚠️ INTRUSO DESCONOCIDO";
    }
} else {
    // Si no hay rostros o dio error por foto vacía
    msg3.payload = "✅ Sin rostros / Escaneando...";
}

return [msg1, msg3];

const data = msg.payload;

// Revisamos si viene la alerta desde MQTT
if (data && data.alerta) {
    let mensaje = "";

    // Armamos el texto según el tipo de alerta
    if (data.alerta === "persona_identificada") {
        mensaje = "📷 Ingreso detectado: " + data.identidad.toUpperCase();
    } else if (data.alerta === "intruso_detectado") {
        mensaje = "🚨 ALERTA: Intruso desconocido en la cámara.";
    }

    // Si hay mensaje, le damos el formato que exige el nodo de Telegram
    if (mensaje !== "") {
        msg.payload = {
            chatId: 1138232122,
            type: "message",
            content: mensaje
        };
        return msg;
    }
}

// Si no hay alerta que nos interese, no hace nada
return null;

const d = msg.payload;
const cooldown = 30000;
const now = Date.now();
let alerts = [];

if (d.distancia < 20) {
    const last = context.get('d_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Distancia crítica!*\nObjeto a ' + Number(d.distancia).toFixed(1) + ' cm');
        context.set('d_alert', now);
    }
}
if (d.gas > 100) {
    const last = context.get('g_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Nivel de gas elevado!*\nValor: ' + d.gas);
        context.set('g_alert', now);
    }
}
if (d.sonido > 80) {
    const last = context.get('s_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Ruido excesivo!*\n' + d.sonido + '%');
        context.set('s_alert', now);
    }
}
if (alerts.length > 0) {
    msg.payload = {
        chatId: '1138232122',
        type: 'message',
        content: '🚨 *ALERTA ESTACIÓN IOT*\n\n' + alerts.join('\n\n')
    };
    return msg;
}
return null;

const chatId = msg.payload.chatId || '1138232122';
const cmd = String(msg.payload.content || '').trim().toUpperCase();

let accion = '';
if (cmd === 'ON' || cmd === '1')           accion = 'ON';
else if (cmd === 'OFF' || cmd === '0')    accion = 'OFF';
else if (cmd === 'TOGGLE' || cmd === 'T') accion = 'TOGGLE';
else {
    return [null, { payload: '❌ Usá: /led ON, /led OFF o /led TOGGLE', chatId: chatId }];
}

return [
    { payload: accion },                    // Output 1 → MQTT
    { payload: '✅ LED ' + accion, chatId: chatId }  // Output 2 → Telegram
];

const estado = String(msg.payload).toUpperCase();
const icono = estado === 'ON' ? '🟢' : '🔴';
msg.payload = icono + ' LED ' + (estado === 'ON' ? 'ENCENDIDO' : 'APAGADO');
msg.chatId = '1138232122';
return msg;

const d = msg.payload;
if (!d || typeof d !== "object") return null;
const data = {
    gas: d.gas != null ? d.gas : 0,
    distancia: d.distancia != null ? d.distancia : 0,
    sonido: d.sonido != null ? d.sonido : 0,
    alerta: d.alerta || ""
};
context.set("sensor_data", data);
// Si no hay datos, en vez de enviar null, enviamos un mensaje vacío 
// que no rompa el gráfico o simplemente no enviamos nada.
return [
    data ? { payload: data } : null,
    data ? { payload: data, topic: "Gas" } : null, // <-- El truco está en agregar el topic aquí
    data ? { payload: data } : null
];

if (msg.payload && msg.payload.type === "Buffer") {
    const buf = Buffer.from(msg.payload.data);
    const b64 = buf.toString("base64");
    msg.payload = "data:image/jpeg;base64," + b64;
    return msg;
}
if (Buffer.isBuffer(msg.payload)) {
    const b64 = msg.payload.toString("base64");
    msg.payload = "data:image/jpeg;base64," + b64;
    return msg;
}
return null;

const d = msg.payload;
if (!d || typeof d !== "object") return null;
context.set("sys_state", { movimiento: d.movimiento || false, alerta: d.alerta || "ninguna", identidad: d.identidad || "", timestamp: Date.now() });
let nivel = "OK";
let mensaje = "Sistema Normal";
let color = "#2ecc71";
if (d.alerta === "intruso_detectado") { nivel = "ALERTA"; mensaje = "INTRUSO DETECTADO"; color = "#e74c3c"; }
else if (d.alerta === "persona_identificada") { nivel = "WARNING"; mensaje = "Identificado: " + (d.identidad || "Desconocido"); color = "#f39c12"; }
msg.payload = { nivel: nivel, mensaje: mensaje, color: color };
return msg;

const d = msg.payload;
if (!d || typeof d !== "object") return null;
let motion = d.movimiento ? "Si" : "No";
let person = "No";
if (d.alerta === "persona_identificada") person = d.identidad || "Si";
else if (d.alerta === "intruso_detectado") person = "Desconocido";
let alertText = "Sin alertas";
if (d.alerta === "intruso_detectado") alertText = "INTRUSO detectado";
else if (d.alerta === "persona_identificada") alertText = "Identificado: " + (d.identidad || "Desconocido");
return [
    { payload: motion },
    { payload: person },
    { payload: alertText }
];

const d = msg.payload;

// Si no hay datos, no hacemos nada
if (!d) return null;

// Extraemos los valores y aseguramos que sean números (si vienen vacíos, ponemos 0)
const sonido = d.sonido || 0;
const gas = d.gas || 0;
const distancia = d.distancia || 0;

// Armamos el texto SQL directamente con los valores (nota las comillas invertidas ` )
msg.topic = `INSERT INTO sensor_history (sonido, gas, distancia) VALUES (${sonido}, ${gas}, ${distancia});`;

// Destruimos el payload para que el nodo SQLite solo ejecute el topic crudo
delete msg.payload;

return msg;

const rows = msg.payload;
if (!rows || !Array.isArray(rows)) return null;

const mensajes = rows.map((row, index) => {
    let textDate = String(row.timestamp);

    // Arreglamos el formato de SQLite "YYYY-MM-DD HH:MM:SS" a "YYYY-MM-DDTHH:MM:SSZ"
    if (textDate.includes(" ") && !textDate.includes("T")) {
        textDate = textDate.replace(" ", "T") + "Z";
    }

    let timeMs = new Date(textDate).getTime();

    // Si por alguna razón extrema la fecha sigue fallando, 
    // separamos los puntos artificialmente para evitar la línea vertical
    if (isNaN(timeMs)) {
        timeMs = Date.now() - ((rows.length - index) * 1000);
    }

    return {
        topic: "Gas",
        payload: row.gas,
        timestamp: timeMs
    };
});

// Enviamos los mensajes en ráfaga
return [ mensajes ];

