const rango = msg.payload;
let sql = "";

if (rango === '1h') {
    sql = "SELECT timestamp, gas FROM sensor_history WHERE timestamp >= datetime('now', '-1 hour') ORDER BY timestamp ASC";
} else if (rango === '24h') {
    sql = "SELECT timestamp, gas FROM sensor_history WHERE timestamp >= datetime('now', '-1 day') ORDER BY timestamp ASC";
} else {
    // Subconsulta para traer los últimos 200 reales y luego ordenarlos cronológicamente
    sql = "SELECT * FROM (SELECT timestamp, gas FROM sensor_history ORDER BY timestamp DESC LIMIT 200) ORDER BY timestamp ASC";
}

msg.topic = sql;
return msg;

